    return (
      <div className="tool-card printer-credential" data-testid={`tool-${activity.actionId}`}>
        <div className="tool-title">{activity.title}</div>
        <div className="tool-state">{activity.state === 'rejected' ? 'Cancelled' : 'Sent'}</div>
