// A model that answers the first message by calling printer_connect with
// `arguments`, and anything after that with a line of text.
class ConnectingAgent final : public Agent::IAgentService
{
public:
    explicit ConnectingAgent(nlohmann::json arguments) : m_arguments(std::move(arguments)) {}

    bool ready() const override { return true; }
    bool busy() const override { return m_active; }
    bool start(const Agent::AgentRequest& request) override
    {
        m_active = true;
        if (request.purpose != Agent::AgentRequest::Purpose::ConversationTitle && !m_called) {
            m_called = true;
            m_events.push_back(Agent::AgentEvent::tool_call({"call-1", Agent::ToolRequest{"printer_connect", m_arguments.dump()}, true}));
        } else {
            m_events.push_back(Agent::AgentEvent::delta("Checking."));
            m_events.push_back(Agent::AgentEvent::completed());
        }
        return true;
    }
    bool continue_after_tool(const Agent::AgentToolResult&) override
    {
        m_events.push_back(Agent::AgentEvent::delta("Checking."));
        m_events.push_back(Agent::AgentEvent::completed());
        return true;
    }
    void cancel() override
    {
        m_active = false;
        m_events.clear();
    }
    std::optional<Agent::AgentEvent> poll() override
    {
        if (m_events.empty())
            return std::nullopt;
        Agent::AgentEvent event = std::move(m_events.front());
        m_events.pop_front();
        if (event.kind == Agent::AgentEventKind::Completed || event.kind == Agent::AgentEventKind::Failed)
            m_active = false;
        return event;
    }

private:
    nlohmann::json                m_arguments;
    std::deque<Agent::AgentEvent> m_events;
    bool                          m_active{false};
    bool                          m_called{false};
};""")

